import{_ as e,o as r,c as t,ag as p}from"./chunks/framework.DzGOF12C.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/China/08. 성리학.md","filePath":"philosophy/China/08. 성리학.md"}'),o={name:"philosophy/China/08. 성리학.md"};function _(i,a,n,s,h,l){return r(),t("div",null,[...a[0]||(a[0]=[p('<p>북송 5자의 우주론과 인성론을 주희가 결합하여 만든것이 성리학</p><p>성리학의 중심 개념<br> 우주 생성론, 심성 가치론</p><h2 id="_1-주희-주자-의-리기이원론-理氣二元論" tabindex="-1">1. 주희(주자)의 리기이원론 (理氣二元論) <a class="header-anchor" href="#_1-주희-주자-의-리기이원론-理氣二元論" aria-label="Permalink to &quot;1. 주희(주자)의 리기이원론 (理氣二元論)&quot;">​</a></h2><p>주자는 인격신을 부정했다<br> 우주의 보편적 법칙인 리와 그것을 현실에 구현하는 기로 세계를 설명한다.<br> 리는 스스로 존재하며 그 원인이 필요하지 않고, 초월해 있으며 가자체로 완전하다.<br> 그러나 리는 능동적으로 행위 하지 않기 떄문에 기가 리를 움직이는 방식으로만 활동이 가능하다.</p><p>이러한 관점을 기반으로 성리학의 우주론인 리기이원론이 나온다</p><p>그러나 리와 기의 관계는 항상 동일하지 않다. 존재물의 생성과정 자체는 가치중립적이지만, 생성된 존재물의 가치의 세계로 진입하기 때문이다.</p><p>생성될 때는 리와 기사이의 우열이 없다. 존재물이 생성되기 위해서는 그 원리인 리와 이를 드러내는 기가 결합한다. 리기불상리, 즉 리와 기는 생성론적 관점에서 분리 되지 않는다.</p><p>그러나 가치세계의 관점에서는 차이가 생긴다. 생성된 존재물은 선과 악으로 구분지어지며 리와 기에 위계가 생긴다. 리는 순선한 것으로 기는 악의 근원으로 받아들여진다. 그러한 가치론적 관점에서 리기불상잡, 즉 리와 기는 섞일수 없이 분리된 상태로 보아야한다는 것이다.</p><h2 id="_2-성리학의-심성론-심·성·정" tabindex="-1">2. 성리학의 심성론 (심·성·정) <a class="header-anchor" href="#_2-성리학의-심성론-심·성·정" aria-label="Permalink to &quot;2. 성리학의 심성론 (심·성·정)&quot;">​</a></h2><p>심성론 또한 리와 기를 통하여 설명한다.<br> 마음을 심, 그 본성을 성, 이로 나오는 감정을 정이라고 할 때, 성리학에서 마음은 성과 정을 포괄한다는 심통성정을 주장한다.<br> 이때 마음의 본질인 성은 리로 존재하며 (성즉리), 이러한 성이 기에 의해 밖으로 드러난 것이 정이다. (성발위정)<br> 본래 성은 리와 동일하게 선하지만 기의 움직임에 따라 선한 감정이 나올수도 악한 감정이 나올 수도 있는 것이다. 따라서 훈련을 통해 기가 성을 잘 드러내는 것이 중요하다</p>',10)])])}const b=e(o,[["render",_]]);export{d as __pageData,b as default};
